import Foundation
import Testing
@testable import GitDB
@testable import iosapp

// Proves the Swift pairing reader agrees with the Go writer.
//
// The record format is defined by pkg/pairing and there is no negotiation: a
// device either opens the record gitd published or it never joins the tailnet.
// A hand-written fixture would only show the reader agreeing with itself, so
// these run against records produced by the real Go writer, regenerated by
// `node webapp/src/lib/pairingFixture.mjs`. The TypeScript reader is tested
// against the same file, so all three implementations are pinned together.
struct PairingRecordCrossLanguageTests {
    private struct Fixture: Decodable {
        struct WirePayload: Decodable {
            let headscale_url: String
            let ca_pem: String
        }

        let secret: String
        let slot: String
        let otherSecret: String
        let payload: WirePayload
        let sealedBase64: String
        let otherSecretSealedBase64: String
    }

    private static func fixture() throws -> Fixture {
        let url = try #require(
            Bundle(for: BundleMarker.self).url(forResource: "pairing.fixture", withExtension: "json"),
            "the generated pairing fixture must be bundled with the tests"
        )
        return try JSONDecoder().decode(Fixture.self, from: try Data(contentsOf: url))
    }

    // Locates the test bundle. Swift Testing has no bundle of its own, and
    // Bundle.module is unavailable in an Xcode test target.
    private final class BundleMarker {}

    private static func sealed(_ base64: String) throws -> Data {
        try #require(Data(base64Encoded: base64))
    }

    // Writer and reader derive the slot independently and never exchange it,
    // so disagreeing by one byte would mean the device polls a slot nobody
    // ever writes to and pairing times out with no explanation.
    @Test func slotDerivationMatchesTheGoWriter() throws {
        let fixture = try Self.fixture()
        let secret = try PairingRecord.parseSecret(fixture.secret)
        #expect(PairingRecord.slot(for: secret) == fixture.slot)
    }

    // The whole point: a record gitd sealed must open on this device with the
    // pairing secret from its own QR.
    @Test func opensARecordSealedByGo() throws {
        let fixture = try Self.fixture()

        let payload = try PairingRecord.open(
            sealed: try Self.sealed(fixture.sealedBase64),
            secretEncoded: fixture.secret
        )

        #expect(payload.headscaleURL == fixture.payload.headscale_url)
        #expect(payload.caPEM == fixture.payload.ca_pem)
    }

    // Slots are public, so an abandoned attempt's record could be replayed at a
    // later one. The outer AEAD is what stops that, and a record written under
    // another secret has to fail rather than half-open.
    @Test func rejectsARecordFromAnotherPairingAttempt() throws {
        let fixture = try Self.fixture()

        #expect(throws: PairingRecord.PairingError.wrongPairingSecret) {
            try PairingRecord.open(
                sealed: try Self.sealed(fixture.otherSecretSealedBase64),
                secretEncoded: fixture.secret
            )
        }
    }

    // The QR is scanned by a camera, and a partial read has to be reported as
    // a bad scan rather than silently producing a slot nobody writes to.
    @Test func rejectsATruncatedSecret() throws {
        let fixture = try Self.fixture()
        let truncated = String(fixture.secret.dropLast(4))

        #expect(throws: PairingRecord.PairingError.self) {
            try PairingRecord.parseSecret(truncated)
        }
    }

    // Round-trips the encoding the QR carries, so a secret this device mints
    // can be read back by the same parser the scanning device uses.
    @Test func mintedSecretsParseBackToTheirOwnSlot() throws {
        let minted = PairingRecord.createSecret()
        let parsed = try PairingRecord.parseSecret(minted.encoded)

        #expect(parsed.count == PairingRecord.secretByteCount)
        #expect(PairingRecord.slot(for: parsed) == minted.slot)
    }

    // Two attempts must land in unrelated slots, or an abandoned attempt would
    // still be pollable by whoever saw its QR.
    @Test func eachAttemptGetsItsOwnSlot() throws {
        #expect(PairingRecord.createSecret().slot != PairingRecord.createSecret().slot)
    }

    // Confirms the fixture's other secret is genuinely different, so
    // rejectsARecordFromAnotherPairingAttempt cannot pass vacuously.
    @Test func theFixturesTwoSecretsDiffer() throws {
        let fixture = try Self.fixture()
        #expect(fixture.secret != fixture.otherSecret)
    }
}
